import itertools


def parse_time(s):
    s = s.strip()
    period = s[-2:]
    h, m = map(int, s[:-2].split(":"))
    if h == 12:
        h = 0
    if period == "PM":
        h += 12
    return h * 60 + m


def format_time(t):
    h = (t // 60) % 24
    m = t % 60
    if h == 0:
        h12, period = 12, "AM"
    elif h < 12:
        h12, period = h, "AM"
    elif h == 12:
        h12, period = 12, "PM"
    else:
        h12, period = h - 12, "PM"
    return f"{h12}:{m:02d}{period}"


